import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { getSaved, toggleSaved } from '../services/api';
import { useAuth } from './AuthContext';

const SavedContext = createContext(null);

export function SavedProvider({ children }) {
  const { user } = useAuth();
  const [savedIds, setSavedIds] = useState(new Set());

  useEffect(() => {
    if (!user) { setSavedIds(new Set()); return; }
    getSaved()
      .then(({ data }) => {
        const ids = (data.properties || []).map(p => p.id || p._id);
        setSavedIds(new Set(ids));
      })
      .catch(() => {});
  }, [user]);

  const isSaved = useCallback((id) => savedIds.has(String(id)), [savedIds]);

  const toggle = useCallback(async (property) => {
    const id = String(property.id || property._id);
    setSavedIds(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
    try {
      await toggleSaved(id);
    } catch {
      // revert
      setSavedIds(prev => {
        const next = new Set(prev);
        next.has(id) ? next.delete(id) : next.add(id);
        return next;
      });
    }
  }, []);

  return (
    <SavedContext.Provider value={{ isSaved, toggle, savedIds }}>
      {children}
    </SavedContext.Provider>
  );
}

export const useSaved = () => useContext(SavedContext);
